/// <summary>
/// AVA/WEN/2025/05/21      AVA_013218_ProdSetupRelease
/// </summary>
/// <param name = "sender">FormDataSource</param>
/// <param name = "e">FormDataSourceEventArgs</param>
[SuppressBPWarning('BPParameterNotUsed', 'False positive'),
    FormDataSourceEventHandler(formDataSourceStr(InventQualityOrderTable, InventQualityOrderTable), FormDataSourceEventType::Activated)]
public static void InventQualityOrderTable_OnActivated(FormDataSource sender, FormDataSourceEventArgs e)
{
    FormFunctionButtonControl   buttonCreateQOrder;
    InventQualityOrderTable inventQualityOrderTable = sender.cursor();
    boolean testGroupExists = false;
    if (InventTable::find(inventQualityOrderTable.ItemId).AVAInventTestGroupId)
    {
        testGroupExists = true;
    }
    buttonCreateQOrder = sender.formRun().design().controlName(formControlStr(InventQualityOrderTable, AVACreateInventQualityOrder));
    buttonCreateQOrder.enabled(testGroupExists);
    //sender.allowCreate(!testGroupExists);
}

/// <summary>
/// AVA/WEN/2025/05/21      AVA_013218_ProdSetupRelease
/// </summary>
/// <param name = "sender">FormDataSource</param>
/// <param name = "e">FormDataSourceEventArgs</param>
[   SuppressBPWarning('BPParameterNotUsed', 'False positive'),
    FormDataSourceEventHandler(formDataSourceStr(InventQualityOrderTable, InventQualityOrderLine), FormDataSourceEventType::Activated)]
public static void InventQualityOrderLine_OnActivated(FormDataSource sender, FormDataSourceEventArgs e)
{
    boolean isOption;
    InventQualityOrderLine  qOrderLine = sender.cursor();
    if (!qOrderLine)
    {
        isOption = false;
    }
    else
    {
        isOption = InventTestTable::find(qOrderLine.TestId).TestType == InventTestType::Option;
    }

    sender.object(fieldNum(InventQualityOrderLine, AVAInventQualityOrderLineResultReal)).enabled(!isOption);
    sender.object(fieldNum(InventQualityOrderLine, AVAInventTestVariableOutcomeId)).enabled(isOption);
}

/// <summary>
/// AVA/WEN/2025/05/21      AVA_013218_ProdSetupRelease
/// </summary>
/// <param name = "sender">FormRun</param>
/// <param name = "e">FormEventArgs</param>
[   SuppressBPWarning('BPParameterNotUsed', 'False positive'),
    FormEventHandler(formStr(InventQualityOrderTable), FormEventType::Activated)]
public static void InventQualityOrderTableFrm_OnActivated(xFormRun sender, FormEventArgs e)
{
    FormFunctionButtonControl   buttonCreateQOrder;
    ProdTable prodTable = sender.args().record();
    boolean testGroupExists = false;
    if (InventTable::find(ProdTable.ItemId).AVAInventTestGroupId)
    {
        testGroupExists = true;
    }
    buttonCreateQOrder = sender.design().controlName(formControlStr(InventQualityOrderTable, AVACreateInventQualityOrder));
    buttonCreateQOrder.enabled(testGroupExists);
}

/// <summary>
/// AVA/WEN/2025/05/21      AVA_013218_ProdSetupRelease
/// </summary>
/// <param name = "sender">FormControl</param>
/// <param name = "e">FormControlEventArgs</param>
[FormControlEventHandler(formControlStr(InventQualityOrderTable, InventQualityOrderLine_AVAInventTestVariableOutcomeId), FormControlEventType::Lookup)]
public static void InventQualityOrderLine_AVAInventTestVariableOutcomeId_OnLookup(FormControl sender, FormControlEventArgs e)
{
    FormControlCancelableSuperEventArgs ce = e as FormControlCancelableSuperEventArgs;
    InventQualityOrderLine qOrderLine = sender.formRun().dataSource(formDataSourceStr(InventQualityOrderTable,InventQualityOrderLine)).cursor();

    InventTestVariableOutcome::lookupVariableOutcomes(sender, qOrderLine.VariableId);

    ce.CancelSuperCall();

}
